function [d] = freq_dependent(gmst, d0)
%FREQ_DEPENDENT  solidtides.freqDependent(gmst, dcs0): the MATLAB's two representative step-2 lines (K1 on (2, 1), argument gmst +
%   pi/2, and 0.47e-11 on C20). Not in forces.solidtides.
%   gmst: real[1] (passed a plain number)
%   d0: Dcs5 (passed rec)
%   returns d: Dcs5 (passed rec)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    d = asils.models.solidtides.Dcs5_zero();
    d = d0;
    th = (gmst + (pi / 2));
    d.dc(3, 2) = (d.dc(3, 2) + ((-(2.9e-12)) * sin(th)));
    d.ds(3, 2) = (d.ds(3, 2) + ((-(2.9e-12)) * cos(th)));
    d.dc(3, 1) = (d.dc(3, 1) + 4.7e-12);
end
